(function(){
 const P=window.SRU_PORTAL; const main=document.getElementById('portal-main'); const nav=document.getElementById('portal-nav');
 let session=JSON.parse(localStorage.getItem('sru_session')||'null');
 const demoKey=new URLSearchParams(location.search).get('demo');
 const demoUsers={admin:{id:'U001',username:'admin',role:'Admin',email:'admin@sruglobal.in',phone:'+919361748842'},contributor:{id:'U002',username:'contributor',role:'Contributor',email:'contributor@sruglobal.in',phone:'+919361748843'},accounts:{id:'U003',username:'accounts',role:'Accounts',email:'accounts@sruglobal.in',phone:'+919361748844'},user:{id:'U004',username:'user',role:'User',email:'user@sruglobal.in',phone:'+919361748845'}};
 if(!session&&demoKey&&demoUsers[demoKey]){session={...demoUsers[demoKey],at:new Date().toISOString()};try{localStorage.setItem('sru_session',JSON.stringify(session))}catch(e){}}
 if(!session){location.href='login.html';return;}
 const perms=P.roles[session.role]||[];
 const labels={dashboard:'Dashboard',catalog:'Catalogue & Stock',crm:'Stock Operations',invoices:'Sales & Invoices',billing:'Purchases, Expenses & Documents',accounts:'Money & Accounts',parties:'Customers & Vendors',employees:'Employees & Payroll',reports:'Reports & Tally',company:'Company Configuration',audit:'Audit & Export','vendor-contributions':'Vendor Contributions','user-admin':'User Admin','menu-admin':'Menu Admin'};
 const routeMap={dashboard:renderDashboard,catalog:renderCatalog,crm:renderCRM,invoices:renderInvoices,billing:renderBilling,accounts:renderAccounts,parties:renderParties,employees:renderEmployees,reports:renderReports,company:renderCompany,audit:renderAudit,'user-admin':renderUsers,'menu-admin':renderMenus};
 function allowed(k){return P.menus[k]!==false && perms.includes(k)}
 function buildNav(){
 const items=perms.filter(k=>k==='dashboard'||allowed(k));
 nav.innerHTML=items.map(k=>{
   if(k==='vendor-contributions') return `<a href="vendor-contributions.html">${labels[k]}</a>`;
   return `<a href="#${k}">${labels[k]}</a>`;
 }).join('')+`<div class="nav-divider"></div><a href="index.html" class="nav-secondary">Public site</a><a href="#logout" id="logout-link" class="nav-secondary">Logout</a>`;
 document.getElementById('logout-link').onclick=e=>{e.preventDefault();localStorage.removeItem('sru_session');location.href='login.html'};
 const current=location.hash.slice(1)||'dashboard';
 nav.querySelectorAll('a[href^="#"]').forEach(a=>{if(a.getAttribute('href')==='#'+current)a.classList.add('active')});
}
 function shell(title,sub,body){main.innerHTML=`<section class="portal-wrap"><div class="portal-heading"><div><p class="eyebrow">SRU GLOBAL · ${session.role.toUpperCase()}</p><h1>${title}</h1><p>${sub}</p></div><div class="session-chip">${session.username}<span>${session.role}</span></div></div>${body}</section>`}
 function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c??''}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
 const money=n=>'₹'+Number(n||0).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
 const now=()=>new Date().toISOString(); const today=()=>new Date().toISOString().slice(0,10); const ym=()=>new Date().toISOString().slice(0,7);
 function lsGet(k,seed=[]){try{const x=JSON.parse(localStorage.getItem(k)||'null');return Array.isArray(x)?x:seed}catch(e){return seed}}
 function lsSet(k,v){localStorage.setItem(k,JSON.stringify(v))}
 function audit(action,type,id,details){const a=lsGet('sru_audit_events');a.push({event_id:'AE'+Date.now(),timestamp:now(),user_id:session.id,username:session.username,role:session.role,action,entity_type:type,entity_id:id,details});lsSet('sru_audit_events',a)}
 function products(){return P.products||[]}
 function stock(){return lsGet('sru_stock',P.stock||[])}
 function saveStock(v){lsSet('sru_stock',v)}
 function accounts(){return lsGet('sru_accounts',P.accounts||[])}
 function vendors(){return lsGet('sru_vendors',P.vendors||[])}
 function saveVendors(v){lsSet('sru_vendors',v)}
 function vendorById(id){return vendors().find(v=>v.vendor_id===id)||null}
 function reorderLinks(x){const v=vendorById(x.vendor_id);if(!v)return '<span class="small-note">Add a preferred vendor</span>';const qty=Math.max(1,Number(x.reorder_level||0)-Number(x.qty_on_hand||0));const msg=encodeURIComponent(`Hi ${v.contact_name||v.name||''}, SRU Global needs a reorder for ${x.product_name}. Current stock: ${x.qty_on_hand}. Reorder quantity: ${qty}. Please share availability, buying price and delivery timeline.`);const mail=encodeURIComponent(`Reorder request – ${x.product_name}`);const body=encodeURIComponent(`Hi ${v.contact_name||v.name||''},%0A%0ASRU Global needs a reorder for ${x.product_name}.%0ACurrent stock: ${x.qty_on_hand}%0AReorder quantity: ${qty}%0APlease share availability, buying price and delivery timeline.`);return `<div class="reorder-actions"><a class="btn small whatsapp-reorder" target="_blank" href="https://wa.me/${String(v.phone||'').replace(/\D/g,'')}?text=${msg}">WhatsApp</a><a class="btn small mail-reorder" href="mailto:${v.email||''}?subject=${mail}&body=${body}">Email</a></div>`}
 function saveAccounts(v){lsSet('sru_accounts',v)}
 function invoiceSeq(){return lsGet('sru_invoice_sequence',[])}
 function generateInvoiceNumber(){const month=ym();const seq=invoiceSeq();let row=seq.find(x=>x.month===month);let n=row?Number(row.next_number||1):1;if(!row){row={month,next_number:n,updated_at:now()};seq.push(row)};const prefix='IN'+String(P.company.name||'SRU Global').replace(/[^A-Za-z]/g,'').slice(0,3).toUpperCase();const d=new Date();const stamp=d.getFullYear()+String(d.getMonth()+1).padStart(2,'0')+String(d.getDate()).padStart(2,'0')+String(d.getHours()).padStart(2,'0')+String(d.getMinutes()).padStart(2,'0');const number=prefix+stamp+String(n).padStart(5,'0');row.next_number=n+1;row.updated_at=now();lsSet('sru_invoice_sequence',seq);return number}
 function updateAccount(id,delta){const a=accounts();const x=a.find(z=>z.account_id===id);if(x){x.current_balance=Number(x.current_balance||0)+Number(delta||0);x.updated_at=now();saveAccounts(a)}}
 function addTxn(t){const arr=lsGet('sru_transactions',P.transactions||[]);arr.push({...t,transaction_id:'T'+Date.now()+Math.floor(Math.random()*100),created_by:session.username,created_at:now()});lsSet('sru_transactions',arr)}
 function adjustStock(pid,qty,dir,unitCost,sourceType,sourceId,accounted=true){const s=stock();let x=s.find(z=>z.portal_product_id===pid||z.sku===pid);if(!x){const p=products().find(z=>z.portal_product_id===pid);if(!p)throw new Error('Product not found in catalogue');x={stock_id:'S'+String(s.length+1).padStart(5,'0'),portal_product_id:pid,sku:p.id||pid,product_name:p.name,brand:p.brand,category:p.category,qty_on_hand:0,buying_price:Number(unitCost||0),selling_price:Number(p.our_price||0),reorder_level:0,updated_at:today(),vendor_id:''};s.push(x)}if(dir==='out'&&Number(x.qty_on_hand)<qty)throw new Error(`Insufficient stock for ${x.product_name}. Available: ${x.qty_on_hand}`);x.qty_on_hand=Number(x.qty_on_hand)+(dir==='in'?qty:-qty);x.updated_at=today();saveStock(s);const mv=lsGet('sru_stock_movements');mv.push({movement_id:'SM'+Date.now(),date:today(),portal_product_id:x.portal_product_id,product_name:x.product_name,movement_type:sourceType,qty_in:dir==='in'?qty:0,qty_out:dir==='out'?qty:0,unit_cost:Number(unitCost||0),value:Number(qty||0)*Number(unitCost||0),source_type:sourceType,source_id:sourceId,accounted:accounted?'yes':'no',created_by:session.username,created_at:now()});lsSet('sru_stock_movements',mv)}
 function renderDashboard(){const s=stock(),tx=lsGet('sru_transactions',P.transactions||[]),inv=lsGet('sru_invoices'),sett=lsGet('sru_settlements',P.settlements||[]);shell('Operations dashboard','Single source of truth for stock, invoices, bills, accounts and settlements.',`<div class="metric-grid"><div><span>Stock value</span><strong>${money(s.reduce((a,x)=>a+Number(x.qty_on_hand||0)*Number(x.buying_price||0),0))}</strong></div><div><span>Invoices this month</span><strong>${inv.filter(x=>String(x.invoice_date||'').startsWith(ym())).length}</strong></div><div><span>Open settlements</span><strong>${money(sett.filter(x=>x.status==='open').reduce((a,x)=>a+Number(x.amount||0),0))}</strong></div><div><span>Sales this month</span><strong>${money(inv.filter(x=>String(x.invoice_date||'').startsWith(ym())).reduce((a,x)=>a+Number(x.subtotal||0),0))}</strong></div><div><span>Low stock</span><strong>${s.filter(x=>Number(x.qty_on_hand||0)<=Number(x.reorder_level||0)).length}</strong></div><div><span>Transactions</span><strong>${tx.length}</strong></div></div><div class="portal-grid"><div class="portal-panel"><h2>Quick actions</h2><div class="quick-grid">${['invoices','billing','accounts','crm','parties','audit'].filter(allowed).map(k=>`<a href="#${k}">${labels[k]} →</a>`).join('')}</div></div><div class="portal-panel"><h2>Control principle</h2><p>Every invoice, bill, stock movement, payment, account transfer, settlement and non-accounted gift is linked by an ID and written to the activity ledger.</p></div></div>`)}
 function renderCatalog(){
 const ps=products().filter(p=>p.row_type==='product');
 shell('Catalogue','One place to add, edit and update products. Every product has a permanent Portal Product ID used everywhere else.',`<div class="portal-panel catalog-actions"><div class="quick-grid"><button class="btn" id="new-product">+ Add product</button><button class="btn secondary" id="bulk-import">Bulk update / import CSV</button><button class="btn secondary" id="export-catalog">Export catalogue CSV</button><a class="btn secondary" href="#crm">Stock &amp; Reorder</a><a class="btn secondary" href="vendor-contributions.html">Vendor Contributions</a></div><p class="small-note">For bulk updates, keep the Portal Product ID column unchanged. Existing products are updated; new rows without an ID receive the next ID automatically.</p></div><div class="portal-panel"><h2>Product master</h2><div class="table-wrap"><table><thead><tr><th>Product ID</th><th>Product</th><th>Brand</th><th>Category</th><th>MRP</th><th>Our Price</th><th>Actions</th></tr></thead><tbody>${ps.map(p=>`<tr><td>${p.portal_product_id||''}</td><td>${escHtml(p.name)}</td><td>${escHtml(p.brand)}</td><td>${escHtml(p.category)}</td><td>${money(p.mrp)}</td><td>${money(p.our_price)}</td><td><button class="btn small" data-edit-product="${p.portal_product_id}">Edit</button></td></tr>`).join('')}</tbody></table></div></div><div id="catalog-editor"></div><div id="bulk-panel"></div>`);
 document.getElementById('new-product').onclick=()=>openProductEditor(null);
 document.getElementById('bulk-import').onclick=()=>openBulkImport();
 document.getElementById('export-catalog').onclick=()=>exportCatalog();
 document.querySelectorAll('[data-edit-product]').forEach(b=>b.onclick=()=>openProductEditor(b.dataset.editProduct));
 }
 function escHtml(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
 function nextProductId(){const nums=products().map(p=>Number(String(p.portal_product_id||'').replace(/\D/g,''))).filter(Boolean);return 'PRD-'+String((Math.max(0,...nums)+1)).padStart(6,'0')}
 function productToForm(p){p=p||{portal_product_id:nextProductId(),id:'',brand:'',name:'',category:'',description:'',image:'',images:'',mrp:'',our_price:'',row_type:'product',category_slug:'',best_seller:'no',sru_special:'no',home_order:''};return `<div class="portal-panel"><h2>${p.id?'Edit product':'Add product'}</h2><form id="product-form" class="grid-form"><label>Portal Product ID<input name="portal_product_id" value="${escHtml(p.portal_product_id)}" readonly></label><label>SKU / Product key<input name="id" value="${escHtml(p.id)}" required></label><label>Brand<input name="brand" value="${escHtml(p.brand)}" required></label><label>Product name<input name="name" value="${escHtml(p.name)}" required></label><label>Category<input name="category" value="${escHtml(p.category)}"></label><label>Category slug<input name="category_slug" value="${escHtml(p.category_slug)}"></label><label>MRP<input name="mrp" type="number" step="0.01" value="${escHtml(p.mrp)}"></label><label>Our Price<input name="our_price" type="number" step="0.01" value="${escHtml(p.our_price)}"></label><label>Best Seller<select name="best_seller"><option ${p.best_seller==='yes'?'selected':''}>yes</option><option ${p.best_seller!=='yes'?'selected':''}>no</option></select></label><label>SRU Special<select name="sru_special"><option ${p.sru_special==='yes'?'selected':''}>yes</option><option ${p.sru_special!=='yes'?'selected':''}>no</option></select></label><label>Image path<input name="image" value="${escHtml(p.image)}" placeholder="assets/products/...jpg"></label><label>Multiple image paths<input name="images" value="${escHtml(p.images||p.image)}" placeholder="photo1.jpg|photo2.jpg|photo3.jpg"></label><label class="wide">Description<textarea name="description">${escHtml(p.description)}</textarea></label><div class="wide"><button class="btn" type="submit">Save product</button> <button class="btn secondary" type="button" id="cancel-product">Cancel</button><p id="product-msg" class="form-message"></p></div></form></div>`}
 function openProductEditor(id){const p=products().find(x=>x.portal_product_id===id);document.getElementById('catalog-editor').innerHTML=productToForm(p);document.getElementById('catalog-editor').scrollIntoView({behavior:'smooth',block:'start'});document.getElementById('cancel-product').onclick=()=>document.getElementById('catalog-editor').innerHTML='';document.getElementById('product-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const arr=products();const obj={...Object.fromEntries(f.entries()),row_type:'product',home_order:p?.home_order||''};if(!obj.images)obj.images=obj.image;const idx=arr.findIndex(x=>x.portal_product_id===obj.portal_product_id);if(idx>=0)arr[idx]={...arr[idx],...obj};else arr.push(obj);lsSet('sru_catalog_products',arr);syncStockFromProduct(obj);audit(idx>=0?'UPDATE_PRODUCT':'ADD_PRODUCT','product',obj.portal_product_id,obj.name);renderCatalog()}}
 function syncStockFromProduct(p){const arr=stock();const x=arr.find(s=>s.portal_product_id===p.portal_product_id);if(x){x.product_name=p.name;x.brand=p.brand;x.category=p.category;x.selling_price=Number(p.our_price||x.selling_price||0);x.updated_at=today();saveStock(arr)}}
 function openBulkImport(){document.getElementById('bulk-panel').innerHTML=`<div class="portal-panel"><h2>Bulk catalogue update</h2><p class="small-note">Upload a CSV exported from this portal, or paste CSV text. Portal Product ID is the key. Leave it blank for a new product.</p><input id="catalog-file" type="file" accept=".csv,text/csv"><textarea id="catalog-paste" class="bulk-text" placeholder="Paste CSV here..."></textarea><button class="btn" id="apply-bulk">Preview & apply</button><button class="btn secondary" id="cancel-bulk">Cancel</button><p id="bulk-msg" class="form-message"></p><div id="bulk-preview"></div></div>`;document.getElementById('cancel-bulk').onclick=()=>document.getElementById('bulk-panel').innerHTML='';document.getElementById('catalog-file').onchange=e=>{const f=e.target.files[0];if(f){const r=new FileReader();r.onload=()=>document.getElementById('catalog-paste').value=r.result;r.readAsText(f)}};document.getElementById('apply-bulk').onclick=()=>{const text=document.getElementById('catalog-paste').value.trim();if(!text)return;const rows=parseCSVText(text);const arr=products();let added=0,updated=0;rows.filter(r=>r.row_type!=='category').forEach(r=>{if(!r.portal_product_id)r.portal_product_id=nextProductIdFrom(arr);r.row_type='product';if(!r.images)r.images=r.image||'';const i=arr.findIndex(x=>x.portal_product_id===r.portal_product_id);if(i>=0){arr[i]={...arr[i],...r};updated++}else{arr.push(r);added++}syncStockFromProduct(r)});lsSet('sru_catalog_products',arr);audit('BULK_UPDATE_CATALOG','catalog','ALL',`Added ${added}, updated ${updated}`);document.getElementById('bulk-msg').textContent=`Done. ${added} added, ${updated} updated.`;setTimeout(renderCatalog,700)}}
 function nextProductIdFrom(arr){const nums=arr.map(p=>Number(String(p.portal_product_id||'').replace(/\D/g,''))).filter(Boolean);return 'PRD-'+String((Math.max(0,...nums)+1)).padStart(6,'0')}
 function parseCSVText(text){const rows=[];let row=[],cell='',q=false;for(let i=0;i<text.length;i++){const c=text[i],n=text[i+1];if(c==='"'){if(q&&n==='"'){cell+='"';i++}else q=!q}else if(c===','&&!q){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&n==='\n')i++;row.push(cell);if(row.some(x=>x!==''))rows.push(row);row=[];cell=''}else cell+=c}if(cell!==''||row.length){row.push(cell);rows.push(row)}const h=rows.shift()||[];return rows.map(r=>Object.fromEntries(h.map((k,i)=>[k,r[i]??'']))) }
 function exportCatalog(){const arr=products();const h=['id','brand','name','category','description','image','images','mrp','our_price','row_type','category_slug','category_title','category_description','best_seller','sru_special','home_order','portal_product_id'];const csv=[h.join(','),...arr.map(x=>h.map(k=>csvCell(x[k])).join(','))].join('\n');download('sru-catalogue-'+today()+'.csv',csv,'text/csv');audit('EXPORT_CATALOG','catalog','ALL','Catalogue CSV exported')}
 function renderCRM(){const s=stock(),vs=vendors();const low=s.filter(x=>Number(x.qty_on_hand||0)<=Number(x.reorder_level||0));shell('Catalogue & Stock','Simple stock control. Change reorder levels anytime. Every low-stock item can be sent to its preferred vendor in one click.',`<div class="portal-grid"><div class="portal-panel"><h2>What needs attention</h2><div class="metric-grid"><div><span>Low / reorder</span><strong>${low.length}</strong></div><div><span>Total units</span><strong>${s.reduce((a,x)=>a+Number(x.qty_on_hand||0),0)}</strong></div></div>${low.length?table(['Product','Qty','Reorder','Preferred vendor','One-click reorder'],low.map(x=>{const v=vendorById(x.vendor_id);return [x.product_name,x.qty_on_hand,x.reorder_level,v?`${escHtml(v.nickname||v.name)}<br><span class="small-note">${escHtml(v.phone||v.email||'')}</span>`:'<span class="warning">Not assigned</span>',reorderLinks(x)]})):'<p>No products are below their reorder level.</p>'}</div><div class="portal-panel"><h2>Quick stock update</h2><form id="stock-move" class="grid-form"><label>Product ID<select name="pid">${s.map(x=>`<option value="${x.portal_product_id}">${x.portal_product_id} · ${escHtml(x.product_name)}</option>`).join('')}</select></label><label>Action<select name="type"><option value="purchase">Received / Purchased</option><option value="gift_in">Received as Gift — not accounted</option><option value="adjustment_in">Add stock correction</option><option value="gift_out">Given as Gift — not accounted</option><option value="adjustment_out">Remove stock correction</option></select></label><label>Quantity<input name="qty" type="number" min="1" required></label><label>Unit cost<input name="cost" type="number" min="0" step="0.01"></label><label>Reorder level<input name="reorder" type="number" min="0" step="1" placeholder="Change reorder level"></label><label>Preferred vendor<select name="vendor_id"><option value="">Select vendor</option>${vs.map(v=>`<option value="${v.vendor_id}">${escHtml(v.nickname||v.name)}</option>`).join('')}</select></label><button class="btn" type="submit">Save stock update</button><p id="stock-msg" class="form-message wide"></p></form></div></div><div class="portal-panel"><h2>Stock master</h2>${table(['Product ID','Product','Qty','Buying cost','Selling price','Reorder level','Preferred vendor','Status'],s.map(x=>{const v=vendorById(x.vendor_id);return [x.portal_product_id,x.product_name,x.qty_on_hand,money(x.buying_price),money(x.selling_price),`<input class="inline-reorder" data-reorder="${x.portal_product_id}" value="${x.reorder_level}" type="number" min="0">`,v?escHtml(v.nickname||v.name):'<span class="warning">Not assigned</span>',Number(x.qty_on_hand)<=Number(x.reorder_level)?'<strong class="warning">REORDER</strong>':'OK']}))}</div>`);document.querySelectorAll('[data-reorder]').forEach(inp=>inp.onchange=()=>{const arr=stock(),x=arr.find(z=>z.portal_product_id===inp.dataset.reorder);if(x){x.reorder_level=Number(inp.value||0);x.updated_at=today();saveStock(arr);audit('UPDATE_REORDER_LEVEL','stock',x.portal_product_id,String(x.reorder_level));renderCRM()}});document.getElementById('stock-move').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),type=f.get('type'),gift=type==='gift_in'||type==='gift_out',dir=(type==='purchase'||type==='gift_in'||type==='adjustment_in')?'in':'out';try{const arr=stock(),x=arr.find(z=>z.portal_product_id===f.get('pid'));if(x){if(f.get('reorder')!=='')x.reorder_level=Number(f.get('reorder'));if(f.get('vendor_id'))x.vendor_id=f.get('vendor_id');saveStock(arr)}adjustStock(f.get('pid'),Number(f.get('qty')),dir,Number(f.get('cost')),type,'MANUAL',!gift);if(gift){const na=lsGet('sru_non_accounted');na.push({record_id:'NA'+Date.now(),date:today(),direction:dir,source_type:type,source_id:'MANUAL',portal_product_id:f.get('pid'),qty:Number(f.get('qty')),unit_cost:Number(f.get('cost')||0),value:Number(f.get('qty'))*Number(f.get('cost')||0),gst_treatment:'Not posted',accounted:'no',created_by:session.username,created_at:now()});lsSet('sru_non_accounted',na)}audit('POST_STOCK_MOVEMENT','stock',f.get('pid'),type);document.getElementById('stock-msg').textContent='Saved. Stock, reorder level and vendor updated.';renderCRM()}catch(err){document.getElementById('stock-msg').textContent=err.message}}}
 function invoiceForm(){const parts=lsGet('sru_parties',[]).filter(x=>x.party_type==='customer'||x.party_type==='customer_vendor'),acc=accounts(),ps=products().filter(x=>x.row_type==='product');return `<form id="invoice-form" class="grid-form"><label>Customer<select name="party_id" id="invoice-party"><option value="">Select customer</option>${parts.map(x=>`<option value="${x.party_id}">${escHtml(x.nickname||x.name)}${x.gst_number?' · GST '+escHtml(x.gst_number):''}</option>`).join('')}</select></label><label>Customer GST<input name="customer_gst" id="invoice-gst"></label><label>GST treatment<select name="gst_treatment"><option value="accounted">GST accounted</option><option value="non_accounted">Gift / value noted — GST not accounted</option></select></label><label>Payment/account<select name="account_id">${acc.map(a=>`<option value="${a.account_id}">${escHtml(a.nickname)}</option>`).join('')}</select></label><label>Payment mode<select name="mode"><option>UPI</option><option>Bank</option><option>Cash</option><option>Card</option><option>Credit</option></select></label><label>Reference<input name="reference"></label><div class="wide"><h3>Products</h3><div id="invoice-lines"></div><button class="btn secondary" type="button" id="add-line">+ Add product</button></div><button class="btn" type="submit">Generate invoice</button><p id="inv-msg" class="form-message wide"></p></form>`}
 function addInvoiceLine(){const box=document.getElementById('invoice-lines');if(!box)return;const ps=products().filter(x=>x.row_type==='product');const row=document.createElement('div');row.className='invoice-line grid-form';row.innerHTML=`<label>Product<select class="line-product">${ps.map(p=>`<option value="${p.portal_product_id}">${escHtml(p.portal_product_id)} · ${escHtml(p.name)}</option>`).join('')}</select></label><label>Qty<input class="line-qty" type="number" min="1" value="1"></label><label>Unit price<input class="line-price" type="number" min="0" step="0.01" value="0"></label><button class="btn small secondary remove-line" type="button">Remove</button>`;box.appendChild(row);const sel=row.querySelector('.line-product'),price=row.querySelector('.line-price');const setPrice=()=>{const p=ps.find(x=>x.portal_product_id===sel.value);price.value=Number(p?.our_price||0)};sel.onchange=setPrice;row.querySelector('.remove-line').onclick=()=>row.remove();setPrice()}
 function printInvoice(id){const inv=lsGet('sru_invoices').find(x=>x.invoice_id===id);if(!inv)return;const lines=lsGet('sru_invoice_lines').filter(x=>x.invoice_id===id);const w=window.open('','_blank');if(!w)return;w.document.write(`<html><head><title>${inv.invoice_number}</title><style>body{font-family:Arial;padding:40px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #ddd;padding:8px}h1{margin-bottom:4px}</style></head><body><h1>${esc(P.company.name)}</h1><p>${esc(P.company.address||'')}<br>GST: ${esc(P.company.gst||'')}</p><h2>Invoice ${esc(inv.invoice_number)}</h2><p>Date: ${esc(inv.invoice_date)}</p><table><tr><th>Product</th><th>Qty</th><th>Price</th><th>Total</th></tr>${lines.map(x=>`<tr><td>${esc(x.product_name)}</td><td>${x.qty}</td><td>${money(x.unit_price)}</td><td>${money(x.line_total)}</td></tr>`).join('')}</table><h3>Subtotal: ${money(inv.subtotal)}</h3><h3>GST: ${money(inv.gst)}</h3><h2>Total: ${money(inv.total)}</h2><script>window.print()</script></body></html>`);w.document.close()}
 function renderInvoices(){const inv=lsGet('sru_invoices');shell('Invoice generation','Create a numbered sales invoice. The invoice number is monthly-sequenced and every posted line automatically reduces stock.',`<div class="portal-panel"><div class="invoice-rule"><strong>Format:</strong> IN + first 3 letters of company + YYYYMMDDHHMM + 5-digit monthly sequence. <span>Sequence resets to 00001 each month.</span></div>${invoiceForm()}</div><div class="portal-panel"><h2>Recent invoices</h2>${table(['Invoice','Date','Account','Total','GST','Status','Action'],inv.slice(-20).reverse().map(x=>[x.invoice_number,x.invoice_date,x.customer_account_id,money(x.total),money(x.gst),x.status,`<button class="btn small" type="button" onclick="printInvoice('${x.invoice_id}')">Print / PDF</button>`]))}</div>`);addInvoiceLine();document.getElementById('add-line').onclick=addInvoiceLine;document.getElementById('invoice-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const lines=[...document.querySelectorAll('.invoice-line')].map(r=>({pid:r.querySelector('.line-product').value,qty:Number(r.querySelector('.line-qty').value),price:Number(r.querySelector('.line-price').value)}));if(!lines.length){document.getElementById('inv-msg').textContent='Add at least one product.';return}const non=f.get('gst_treatment')==='non_accounted';try{lines.forEach(l=>adjustStock(l.pid,l.qty,'out',l.price,'sale', 'PENDING', !non));const number=generateInvoiceNumber();const subtotal=lines.reduce((a,l)=>a+l.qty*l.price,0);const gst=non?0:subtotal*0.18;const total=subtotal+gst;const id='INV'+Date.now();const inv=lsGet('sru_invoices');inv.push({invoice_id:id,invoice_number:number,invoice_date:now(),company_id:'C001',customer_account_id:f.get('account_id'),subtotal,gst,total,status:'posted',accounted:non?'no':'yes',created_by:session.username,created_at:now(),mode:f.get('mode'),reference:f.get('reference')});lsSet('sru_invoices',inv);const il=lsGet('sru_invoice_lines');lines.forEach((l,i)=>{const p=products().find(x=>x.portal_product_id===l.pid);il.push({invoice_id:id,line_no:i+1,portal_product_id:l.pid,product_name:p?.name||l.pid,qty:l.qty,unit_price:l.price,gst_rate:non?0:18,gst_amount:non?0:l.qty*l.price*0.18,line_total:l.qty*l.price});const mv=lsGet('sru_stock_movements');const last=mv.slice(-1)[0];if(last&&last.source_id==='PENDING')last.source_id=number;lsSet('sru_stock_movements',mv)});lsSet('sru_invoice_lines',il);if(!non){addTxn({date:today(),type:'sale',account_from:f.get('account_id'),account_to:'A001',amount:total,mode:f.get('mode'),reference:f.get('reference'),category:'sale',description:'Invoice '+number,bill_id:id,status:'posted'})}else{const na=lsGet('sru_non_accounted');na.push({record_id:'NA'+Date.now(),date:today(),direction:'out',source_type:'invoice',source_id:id,party:f.get('account_id'),value:subtotal,reason:'Gift sale / value noted but not accounted',gst_treatment:'Not posted',accounted:'no',created_by:session.username,created_at:now()});lsSet('sru_non_accounted',na)}audit('CREATE_INVOICE','invoice',id,number);document.getElementById('inv-msg').textContent=`Invoice ${number} generated. Stock adjusted automatically.`;renderInvoices()}catch(err){document.getElementById('inv-msg').textContent=err.message}}}
 function renderBilling(){const bills=lsGet('sru_bills',P.bills||[]),parts=lsGet('sru_parties',[]).filter(x=>x.party_type==='vendor'||x.party_type==='customer_vendor'),acc=accounts(),ps=products().filter(x=>x.row_type==='product');shell('Billing & Documents','One place for purchase bills, expenses, salary and supporting documents. Vendor GST is taken from the party master so you do not type it repeatedly.',`<div class="portal-panel"><form id="billing-form" class="grid-form"><label>What are you recording?<select name="type"><option value="purchase">Purchase / stock bill</option><option value="expense">Business expense</option><option value="gift_in">Vendor gift received — value noted, not accounted</option><option value="salary">Salary</option></select></label><label>Vendor / party<select name="party_id"><option value="">Select</option>${parts.map(x=>`<option value="${x.party_id}">${escHtml(x.nickname||x.name)}${x.gst_number?' · GST '+escHtml(x.gst_number):''}</option>`).join('')}</select></label><label>Vendor GST<input name="gst_number" id="billing-gst" placeholder="Auto-filled from vendor"></label><label>Product<select name="pid"><option value="">Not stock-related</option>${ps.map(x=>`<option value="${x.portal_product_id}">${x.portal_product_id} · ${escHtml(x.name)}</option>`).join('')}</select></label><label>Quantity<input name="qty" type="number" min="1"></label><label>Unit cost / amount<input name="cost" type="number" min="0" step="0.01" required></label><label>GST %<input name="gst_rate" type="number" min="0" step="0.01" value="18"></label><label>Account<select name="account_id">${acc.map(a=>`<option value="${a.account_id}">${escHtml(a.nickname)}</option>`).join('')}</select></label><label>Payment mode<select name="mode"><option>Bank</option><option>UPI</option><option>Cash</option><option>Card</option><option>Credit</option></select></label><label>Reference<input name="reference"></label><label>Bill number<input name="bill_number"></label><label class="wide">Description<textarea name="description"></textarea></label><label>Attach bill<input name="file" type="file" accept="application/pdf,image/*"></label><button class="btn" type="submit">Save transaction & bill</button><p id="bill-msg" class="form-message wide"></p></form></div><div class="portal-panel"><h2>Recent billing records</h2>${table(['ID','Date','Type','Party','Vendor GST','Subtotal','GST','Total','Accounted'],bills.slice(-30).reverse().map(x=>[x.bill_id,x.date,x.bill_type,x.party,x.gst_number||'',money(x.subtotal),money(x.gst),money(x.total),x.accounted]))}</div>`);document.getElementById('billing-form').addEventListener('change',e=>{if(e.target.name==='party_id'){const p=parts.find(x=>x.party_id===e.target.value);document.getElementById('billing-gst').value=p?.gst_number||''}});document.getElementById('billing-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),type=f.get('type'),qty=Number(f.get('qty')||0),cost=Number(f.get('cost')||0),rate=Number(f.get('gst_rate')||0),party=parts.find(x=>x.party_id===f.get('party_id')),non=type==='gift_in',subtotal=type==='salary'||type==='expense'?cost:qty*cost,gst=non?0:subtotal*rate/100,total=subtotal+gst,id='B'+Date.now();try{if((type==='purchase'||type==='gift_in')&&qty)adjustStock(f.get('pid'),qty,'in',cost,type,id,!non);const arr=lsGet('sru_bills',P.bills||[]);arr.push({bill_id:id,date:today(),bill_type:type,party:party?.nickname||party?.name||'',party_id:party?.party_id||'',gst_number:party?.gst_number||f.get('gst_number'),subtotal,gst,total,account:f.get('account_id'),mode:f.get('mode'),reference:f.get('reference'),bill_number:f.get('bill_number'),description:f.get('description'),accounted:non?'no':'yes',status:'posted',created_by:session.username,created_at:now(),document_name:f.get('file')?.name||''});lsSet('sru_bills',arr);if(type==='purchase'||type==='expense'||type==='salary'){addTxn({date:today(),type,account_from:f.get('account_id'),account_to:party?.party_id||('EXPENSE_'+type.toUpperCase()),amount:total,mode:f.get('mode'),reference:f.get('reference'),category:type,description:f.get('description')||type+' transaction',bill_id:id,status:'posted'});updateAccount(f.get('account_id'),-total)}if(non){const na=lsGet('sru_non_accounted');na.push({record_id:'NA'+Date.now(),date:today(),direction:'in',source_type:type,source_id:id,party:party?.party_id||'',portal_product_id:f.get('pid'),qty,unit_cost:cost,value:subtotal,gst_treatment:'Not posted',accounted:'no',created_by:session.username,created_at:now()});lsSet('sru_non_accounted',na)}audit('CREATE_BILL','bill',id,type);document.getElementById('bill-msg').textContent='Saved. Stock and the central transaction ledger were updated.';renderBilling()}catch(err){document.getElementById('bill-msg').textContent=err.message}}}
 function renderAccounts(){const a=accounts(),tx=lsGet('sru_transactions',P.transactions||[]),sett=lsGet('sru_settlements',P.settlements||[]);shell('Accounts & daily tally','Every account can be added dynamically. Record company, customer, vendor, friend or personal movements and settle them later.',`<div class="portal-grid"><div class="portal-panel"><h2>Add account</h2><form id="acct-form" class="grid-form"><label>Nickname<input name="nickname" placeholder="Ravi / HDFC / Auntie" required></label><label>Type<select name="type"><option>company</option><option>customer</option><option>vendor</option><option>friend</option><option>personal</option><option>cash</option><option>bank</option></select></label><label>Name<input name="name"></label><label>Phone<input name="phone"></label><label>Email<input name="email"></label><button class="btn" type="submit">Add account</button></form><p id="acct-msg" class="form-message"></p></div><div class="portal-panel"><h2>Accounts</h2>${table(['ID','Nickname','Type','Name','Balance','Status'],a.map(x=>[x.account_id,x.nickname,x.account_type,x.holder_name,money(x.current_balance),x.status]))}</div></div><div class="portal-panel"><h2>Record movement</h2><form id="txn-form" class="grid-form"><label>From<select name="from">${a.map(x=>`<option value="${x.account_id}">${x.nickname}</option>`).join('')}</select></label><label>To<select name="to">${a.map(x=>`<option value="${x.account_id}">${x.nickname}</option>`).join('')}</select></label><label>Amount<input name="amount" type="number" step="0.01" min="0" required></label><label>Mode<select name="mode"><option>UPI</option><option>Bank</option><option>Cash</option><option>Card</option><option>NEFT</option></select></label><label>Reference<input name="reference"></label><label>Category<select name="category"><option>buying</option><option>selling</option><option>expense</option><option>settlement</option><option>transfer</option><option>personal</option></select></label><button class="btn" type="submit">Post transaction</button></form></div><div class="portal-panel"><h2>Daily tally / discrepancy</h2>${table(['Date','Money In','Money Out','Net'],[[today(),money(tx.filter(x=>x.date===today()).filter(x=>x.account_to==='A001').reduce((s,x)=>s+Number(x.amount||0),0)),money(tx.filter(x=>x.date===today()).filter(x=>x.account_from==='A001').reduce((s,x)=>s+Number(x.amount||0),0)),money(0)]])}<p class="small-note">Open give/take differences remain in the settlement queue and carry forward until fixed.</p>${table(['Settlement','From','To','Amount','Status','Action'],sett.filter(x=>x.status==='open').map(x=>[x.settlement_id,x.account_from,x.account_to,money(x.amount),x.status,`<button class="btn small" type="button" onclick="settleItem('${x.settlement_id}')">Settle / Fix</button>`]))}</div>`);document.getElementById('acct-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const arr=accounts();const id='A'+String(arr.length+1).padStart(3,'0');arr.push({account_id:id,nickname:f.get('nickname'),account_type:f.get('type'),holder_name:f.get('name'),phone:f.get('phone'),email:f.get('email'),opening_balance:0,current_balance:0,status:'active'});saveAccounts(arr);audit('ADD_ACCOUNT','account',id,f.get('nickname'));document.getElementById('acct-msg').textContent='Account added. It is immediately available in billing and invoice forms.';renderAccounts()};document.getElementById('txn-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),amt=Number(f.get('amount'));updateAccount(f.get('from'),-amt);updateAccount(f.get('to'),amt);addTxn({date:today(),type:'transfer',account_from:f.get('from'),account_to:f.get('to'),amount:amt,mode:f.get('mode'),reference:f.get('reference'),category:f.get('category'),description:'Manual account transaction',status:'posted'});audit('POST_TRANSACTION','transaction',Date.now(),f.get('category'));renderAccounts()}}
 function renderParties(){const p=lsGet('sru_parties',[]);shell('Customers & Vendors','One master for every outside person or business. A party can be a customer, vendor, both, friend or other. Contact details and GST stay here and are reused everywhere.',`<div class="portal-panel"><form id="party-form" class="grid-form"><label>Party type<select name="type"><option>customer</option><option>vendor</option><option>customer_vendor</option><option>friend</option><option>other</option></select></label><label>Nickname<input name="nickname" placeholder="ABC / Ravi / Vendor 1" required></label><label>Name<input name="name" required></label><label>Contact person<input name="contact"></label><label>GST number<input name="gst"></label><label>Phone<input name="phone"></label><label>Email<input name="email" type="email"></label><label class="wide">Address<textarea name="address"></textarea></label><button class="btn" type="submit">Add party</button><p id="party-msg" class="form-message wide"></p></form></div><div class="portal-panel"><h2>Party master</h2>${table(['ID','Type','Nickname','Name','Contact','GST','Phone','Email','Status'],p.map(x=>[x.party_id,x.party_type,x.nickname,x.name,x.contact_name||'',x.gst_number||'',x.phone||'',x.email||'',x.status||'active']))}</div>`);document.getElementById('party-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),arr=lsGet('sru_parties',[]),id='PTY'+String(arr.length+1).padStart(5,'0');const x={party_id:id,party_type:f.get('type'),nickname:f.get('nickname'),name:f.get('name'),contact_name:f.get('contact'),gst_number:f.get('gst'),phone:f.get('phone'),email:f.get('email'),address:f.get('address'),status:'active'};arr.push(x);lsSet('sru_parties',arr);if(x.party_type.includes('vendor')){const vs=lsGet('sru_vendors',P.vendors||[]);vs.push({vendor_id:id,nickname:x.nickname,name:x.name,contact_name:x.contact_name,phone:x.phone,email:x.email,gst_number:x.gst_number,address:x.address,status:'active'});lsSet('sru_vendors',vs)}audit('ADD_PARTY','party',id,x.nickname);document.getElementById('party-msg').textContent='Saved. This party can now be selected in sales, purchases, payments and settlements.';renderParties()}}
 function renderEmployees(){const es=lsGet('sru_employees',[]);shell('Employees & payroll','Keep employee details, salary and portal access together. Salary payments become normal business transactions and appear in daily/monthly reporting.',`<div class="portal-panel"><form id="emp-form" class="grid-form"><label>Employee name<input name="name" required></label><label>Nickname<input name="nickname" required></label><label>Phone<input name="phone"></label><label>Email<input name="email" type="email"></label><label>Role<select name="role"><option>Employee</option><option>Manager</option><option>Accounts</option><option>Contributor</option><option>Admin</option></select></label><label>Monthly salary<input name="salary" type="number" min="0" step="0.01"></label><label>Portal user?<select name="portal"><option value="no">No</option><option value="yes">Yes</option></select></label><label>Status<select name="status"><option>active</option><option>inactive</option></select></label><button class="btn" type="submit">Add employee</button></form></div><div class="portal-panel"><h2>Employee master</h2>${table(['ID','Employee','Nickname','Phone','Email','Role','Monthly salary','Portal user','Status'],es.map(x=>[x.employee_id,x.name,x.nickname,x.phone||'',x.email||'',x.role,money(x.monthly_salary),x.portal_user,x.status]))}</div><div class="portal-panel"><h2>Pay salary</h2><form id="salary-form" class="grid-form"><label>Employee<select name="employee_id">${es.filter(x=>x.status==='active').map(x=>`<option value="${x.employee_id}">${escHtml(x.nickname||x.name)}</option>`).join('')}</select></label><label>Amount<input name="amount" type="number" min="0" step="0.01" required></label><label>Pay from account<select name="account_id">${accounts().map(a=>`<option value="${a.account_id}">${escHtml(a.nickname)}</option>`).join('')}</select></label><label>Mode<select name="mode"><option>Bank</option><option>UPI</option><option>Cash</option></select></label><label>Reference<input name="reference"></label><button class="btn" type="submit">Record salary payment</button><p id="salary-msg" class="form-message wide"></p></form></div>`);document.getElementById('emp-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),arr=lsGet('sru_employees',[]),id='EMP'+String(arr.length+1).padStart(5,'0');arr.push({employee_id:id,name:f.get('name'),nickname:f.get('nickname'),phone:f.get('phone'),email:f.get('email'),role:f.get('role'),monthly_salary:Number(f.get('salary')||0),portal_user:f.get('portal'),status:f.get('status'),created_at:now()});lsSet('sru_employees',arr);audit('ADD_EMPLOYEE','employee',id,f.get('nickname'));renderEmployees()};document.getElementById('salary-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),amt=Number(f.get('amount')),emp=es.find(x=>x.employee_id===f.get('employee_id'));if(!emp)return;updateAccount(f.get('account_id'),-amt);addTxn({date:today(),type:'salary',account_from:f.get('account_id'),account_to:'EXPENSE_SALARY',amount:amt,mode:f.get('mode'),reference:f.get('reference'),category:'salary',description:'Salary - '+emp.name,status:'posted'});audit('PAY_SALARY','employee',emp.employee_id,String(amt));document.getElementById('salary-msg').textContent='Salary recorded in the same transaction ledger. It will appear in daily/monthly reports.';renderEmployees()}}
 function renderReports(){const tx=lsGet('sru_transactions',P.transactions||[]),inv=lsGet('sru_invoices'),b=lsGet('sru_bills',P.bills||[]),s=stock(),sett=lsGet('sru_settlements',P.settlements||[]),parts=lsGet('sru_parties',[]);shell('Reports & Tally','One reporting view for sales, purchases, profit/loss, account settlements and tally mismatches. Filter by period and party.',`<div class="portal-panel"><form id="report-filter" class="grid-form"><label>From<input type="date" name="from"></label><label>To<input type="date" name="to"></label><label>Customer / Vendor<select name="party"><option value="">All parties</option>${parts.map(x=>`<option value="${x.party_id}">${escHtml(x.nickname||x.name)}</option>`).join('')}</select></label><button class="btn" type="submit">Apply report</button><button class="btn secondary" type="button" id="clear-report">Current month</button></form></div><div id="report-output"></div>`);const out=document.getElementById('report-output');function draw(from,to,party){const inRange=x=>{const d=String(x.date||x.invoice_date||'').slice(0,10);return (!from||d>=from)&&(!to||d<=to)&&( !party || x.party_id===party || x.customer_party_id===party || x.vendor_party_id===party || x.party===party || x.account_to===party || x.account_from===party)};const tr=tx.filter(inRange),ii=inv.filter(inRange),bb=b.filter(inRange),ss=sett.filter(x=>(!from||String(x.date||'')>=from)&&(!to||String(x.date||'')<=to)&&( !party || x.party_id===party || x.account_from===party || x.account_to===party));const sales=ii.filter(x=>x.status==='posted').reduce((n,x)=>n+Number(x.subtotal||0),0);const purchase=bb.filter(x=>x.bill_type==='purchase').reduce((n,x)=>n+Number(x.subtotal||0),0);const expenses=bb.filter(x=>['expense','salary'].includes(x.bill_type)).reduce((n,x)=>n+Number(x.subtotal||0),0);const gross=sales-purchase-expenses;const moneyIn=tr.filter(x=>['sale','receipt'].includes(x.type)).reduce((n,x)=>n+Number(x.amount||0),0);const moneyOut=tr.filter(x=>['purchase','expense','salary','payment'].includes(x.type)).reduce((n,x)=>n+Number(x.amount||0),0);const open=ss.filter(x=>x.status==='open').reduce((n,x)=>n+Number(x.amount||0),0);const accountBalances=accounts().map(a=>{const ins=tr.filter(x=>x.account_to===a.account_id).reduce((n,x)=>n+Number(x.amount||0),0),outs=tr.filter(x=>x.account_from===a.account_id).reduce((n,x)=>n+Number(x.amount||0),0);return [a.nickname,money(ins),money(outs),money(Number(a.opening_balance||0)+ins-outs)]});const mismatch=accountBalances.filter(r=>Number(String(r[3]).replace(/[^0-9.-]/g,''))<0);out.innerHTML=`<div class="metric-grid"><div><span>Sales</span><strong>${money(sales)}</strong></div><div><span>Purchase</span><strong>${money(purchase)}</strong></div><div><span>Profit / loss</span><strong>${money(gross)}</strong></div><div><span>Open settlements</span><strong>${money(open)}</strong></div><div><span>Money in</span><strong>${money(moneyIn)}</strong></div><div><span>Money out</span><strong>${money(moneyOut)}</strong></div><div><span>Invoices</span><strong>${ii.length}</strong></div><div><span>Bills</span><strong>${bb.length}</strong></div></div><div class="portal-grid"><div class="portal-panel"><h2>Account input / output</h2>${table(['Account','Input','Output','Calculated balance'],accountBalances)}</div><div class="portal-panel"><h2>Settlement & tally check</h2><p>${ss.filter(x=>x.status==='open').length} settlement(s) still open.</p><p>${mismatch.length} account(s) have a negative calculated balance / tally mismatch.</p>${ss.filter(x=>x.status==='open').length?table(['Settlement','From','To','Amount','Status'],ss.filter(x=>x.status==='open').map(x=>[x.settlement_id,x.account_from,x.account_to,money(x.amount),x.status])):'<p>No open settlements in the selected period.</p>'}</div></div><div class="portal-panel"><h2>Selected-period transactions</h2>${table(['Date','Type','Description','Amount','From','To','Reference'],tr.slice().reverse().map(x=>[x.date,x.type,x.description,money(x.amount),x.account_from,x.account_to,x.reference||'']))}</div>`}const m=ym();draw(m+'-01',today(),'');document.getElementById('report-filter').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);draw(f.get('from'),f.get('to'),f.get('party'))};document.getElementById('clear-report').onclick=()=>{document.querySelector('#report-filter [name=from]').value=m+'-01';document.querySelector('#report-filter [name=to]').value=today();document.querySelector('#report-filter [name=party]').value='';draw(m+'-01',today(),'')}}

 function renderVendors(){return renderParties()}
 function renderBills(){return renderBilling()}
 function renderCompany(){shell('Company configuration','Master identity used by invoices, portal displays and public-site actions.',`<div class="portal-panel"><form id="company-form" class="grid-form company-form"><label>Company name<input name="name" value="${P.company.name}"></label><label>Nickname<input name="nickname" value="${P.company.nickname}"></label><label>Logo path<input name="logo" value="${P.company.logo}"></label><label>GST number<input name="gst" value="${P.company.gst}"></label><label>Udyam number<input name="udyam" value="${P.company.udyam}"></label><label>Phone<input name="phone" value="${P.company.phone}"></label><label>Email<input name="email" value="${P.company.email}"></label><label>Website<input name="website" value="${P.company.website}"></label><label class="wide">Address<textarea name="address">${P.company.address}</textarea></label><button class="btn" type="submit">Save master configuration</button><p id="company-msg" class="form-message wide"></p></form></div>`);document.getElementById('company-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);Object.assign(P.company,{name:f.get('name'),nickname:f.get('nickname'),logo:f.get('logo'),gst:f.get('gst'),udyam:f.get('udyam'),phone:f.get('phone'),email:f.get('email'),website:f.get('website'),address:f.get('address')});lsSet('sru_company',P.company);audit('UPDATE_COMPANY','company','C001','Master configuration updated');document.getElementById('company-msg').textContent='Company configuration saved. New invoice numbers will use the configured company name.'}}
 function renderAudit(){const ev=lsGet('sru_audit_events');shell('Audit & export','Export the operational ledger for your auditor. The export includes invoices, lines, bills, stock movements, accounts, transactions, payments, settlements and non-accounted items.',`<div class="portal-panel"><div class="quick-grid"><button class="btn" id="export-json">Export full audit JSON</button><button class="btn secondary" id="export-csv">Export transactions CSV</button></div><h2>Recent audit events</h2>${table(['Time','User','Action','Entity','ID','Details'],ev.slice(-50).reverse().map(x=>[new Date(x.timestamp).toLocaleString(),x.username,x.action,x.entity_type,x.entity_id,x.details]))}</div>`);document.getElementById('export-json').onclick=()=>{const payload={exported_at:now(),company:P.company,products:products(),stock:stock(),accounts:accounts(),invoices:lsGet('sru_invoices'),invoice_lines:lsGet('sru_invoice_lines'),bills:lsGet('sru_bills'),transactions:lsGet('sru_transactions',P.transactions||[]),stock_movements:lsGet('sru_stock_movements'),settlements:lsGet('sru_settlements',P.settlements||[]),parties:lsGet('sru_parties'),non_accounted:lsGet('sru_non_accounted'),documents:lsGet('sru_bill_docs'),audit_events:ev,invoice_sequence:invoiceSeq()};download('sru-audit-export-'+today()+'.json',JSON.stringify(payload,null,2),'application/json');audit('EXPORT_AUDIT','audit','JSON','Full audit export')};document.getElementById('export-csv').onclick=()=>{const tx=lsGet('sru_transactions',P.transactions||[]);const csv=['transaction_id,date,type,account_from,account_to,amount,mode,reference,category,description,status,created_by,created_at',...tx.map(x=>[x.transaction_id,x.date,x.type,x.account_from,x.account_to,x.amount,x.mode,x.reference,x.category,x.description,x.status,x.created_by,x.created_at].map(csvCell).join(','))].join('\n');download('sru-transactions-'+today()+'.csv',csv,'text/csv');audit('EXPORT_AUDIT','audit','CSV','Transactions export')}}
 function csvCell(v){return '"'+String(v??'').replace(/"/g,'""')+'"'}
 function download(name,text,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
 function renderUsers(){if(session.role!=='Admin')return renderDenied();shell('User administration','Admin-only user management.',`<div class="portal-panel">${table(['Username','Email','Role','Status'],P.users.map(u=>[u.username,u.email,u.role,u.status]))}</div>`)}
 function renderMenus(){if(session.role!=='Admin')return renderDenied();shell('Menu administration','Admin-only visibility controls.',`<div class="portal-panel"><div class="menu-admin-grid">${Object.keys(labels).filter(k=>k!=='dashboard').map(k=>`<label><input type="checkbox" data-menu="${k}" ${P.menus[k]!==false?'checked':''}> ${labels[k]}</label>`).join('')}</div><button class="btn" id="save-menus">Save menu settings</button><p id="menu-result" class="form-message"></p></div>`);document.getElementById('save-menus').onclick=()=>{document.querySelectorAll('[data-menu]').forEach(c=>P.menus[c.dataset.menu]=c.checked);lsSet('sru_menu_config',P.menus);audit('UPDATE_MENU','menu','ALL','Menu visibility updated');document.getElementById('menu-result').textContent='Menu settings saved.';buildNav()}}
 function renderDenied(){shell('Access restricted','Your current role does not have permission to open this module.',`<div class="portal-panel"><h2>Admin-controlled access</h2><p>Ask an administrator to enable the required menu and role permission.</p></div>`)}
 function route(){let key=location.hash.slice(1)||'dashboard';if(key==='logout'){localStorage.removeItem('sru_session');location.href='login.html';return}if(!routeMap[key]||!allowed(key)&&key!=='dashboard')key='dashboard';routeMap[key]();window.scrollTo({top:0,behavior:'instant'})}
 // Seed persistent ledgers from P only once.
 [['sru_catalog_products',P.products||[]],['sru_stock',P.stock||[]],['sru_accounts',P.accounts||[]],['sru_transactions',P.transactions||[]],['sru_settlements',P.settlements||[]],['sru_bills',P.bills||[]],['sru_parties',[]],['sru_vendors',P.vendors||[]],['sru_employees',[]],['sru_invoices',[]],['sru_invoice_lines',[]],['sru_stock_movements',[]],['sru_non_accounted',[]],['sru_bill_docs',[]],['sru_audit_events',[]],['sru_invoice_sequence',[]]].forEach(([k,v])=>{if(localStorage.getItem(k)===null)lsSet(k,v)});
 const saved=JSON.parse(localStorage.getItem('sru_menu_config')||'null');if(saved)P.menus={...P.menus,...saved};const savedCompany=JSON.parse(localStorage.getItem('sru_company')||'null');if(savedCompany)P.company={...P.company,...savedCompany};buildNav();
 const sidebar=document.getElementById('portal-sidebar'),menuBtn=document.getElementById('portal-menu-toggle'),backdrop=document.getElementById('portal-sidebar-backdrop');
 function closeSidebar(){sidebar&&sidebar.classList.remove('open');backdrop&&backdrop.classList.remove('open');menuBtn&&menuBtn.setAttribute('aria-expanded','false')}
 if(menuBtn){menuBtn.onclick=()=>{const open=!sidebar.classList.contains('open');sidebar.classList.toggle('open',open);backdrop.classList.toggle('open',open);menuBtn.setAttribute('aria-expanded',String(open))}}
 if(backdrop)backdrop.onclick=closeSidebar;
 nav.addEventListener('click',()=>{if(window.innerWidth<=700)closeSidebar()});
 window.addEventListener('hashchange',()=>{buildNav();route()});
 route();
})();
